using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval: GetTypeInfo<T>()
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"Serialized: {json}");

// 2) Probe without throwing: TryGetTypeInfo()
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? found))
    Console.WriteLine($"TryGet succeeded for Person -> {found!.Type.Name}");
else
    Console.WriteLine("TryGet: Person metadata not available");

// Probe a type whose metadata might NOT be resolvable
// (use a resolver that resolves nothing)
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine() // empty — resolves nothing
};

if (limited.TryGetTypeInfo(typeof(Person), out _))
    Console.WriteLine("TryGet succeeded for Person on limited options");
else
    Console.WriteLine("TryGet: Person metadata NOT available (no throw!)");

